#include <vector>
#include <algorithm>

class Solution {
public:
    int memo[1001];
    int dfs(int i, const std::vector<int>& arr, int d, int n) {
        if (memo[i] != 0) return memo[i];
        int ans = 1;
        for (int step : {1, -1}) {
            for (int dist = 1; dist <= d; ++dist) {
                int j = i + step * dist;
                if (j < 0 || j >= n || arr[j] >= arr[i]) break;
                ans = std::max(ans, 1 + dfs(j, arr, d, n));
            }
        }
        return memo[i] = ans;
    }
    int maxJumps(std::vector<int>& arr, int d) {
        int n = arr.size();
        std::fill(memo, memo + n, 0);
        int res = 1;
        for (int i = 0; i < n; ++i) {
            res = std::max(res, dfs(i, arr, d, n));
        }
        return res;
    }
};

class Solution {
    private int[] memo;
    private int dfs(int i, int[] arr, int d, int n) {
        if (memo[i] != 0) return memo[i];
        int ans = 1;
        int[] steps = {1, -1};
        for (int step : steps) {
            for (int dist = 1; dist <= d; dist++) {
                int j = i + step * dist;
                if (j < 0 || j >= n || arr[j] >= arr[i]) break;
                ans = Math.max(ans, 1 + dfs(j, arr, d, n));
            }
        }
        return memo[i] = ans;
    }
    public int maxJumps(int[] arr, int d) {
        int n = arr.length;
        memo = new int[n];
        int res = 1;
        for (int i = 0; i < n; i++) {
            res = Math.max(res, dfs(i, arr, d, n));
        }
        return res;
    }
}

var maxJumps = function(arr, d) {
    const n = arr.length;
    const memo = new Int32Array(n);
    const dfs = (i) => {
        if (memo[i] !== 0) return memo[i];
        let ans = 1;
        for (const step of [1, -1]) {
            for (let dist = 1; dist <= d; dist++) {
                const j = i + step * dist;
                if (j < 0 || j >= n || arr[j] >= arr[i]) break;
                const cand = 1 + dfs(j);
                if (cand > ans) ans = cand;
            }
        }
        return memo[i] = ans;
    };
    let res = 1;
    for (let i = 0; i < n; i++) {
        const val = dfs(i);
        if (val > res) res = val;
    }
    return res;
};
